// src/display/host_registry.cpp -- the backend list, from host_list.inc.
//
// host_list.inc is generated by CMake (lx_display_host) as one
// LX_DISPLAY_HOST(name) line per backend linked into this executable.
#include "core/host_registry.hpp"

#include <algorithm>
#include <array>

#define LX_DISPLAY_HOST(n) const ::lx::display::HostBackend& lx_display_host_##n();
#include "host_list.inc"
#undef LX_DISPLAY_HOST

namespace lx::display {

namespace {

auto sorted_backends() {
    std::array list{
#define LX_DISPLAY_HOST(n) &::lx_display_host_##n(),
#include "host_list.inc"
#undef LX_DISPLAY_HOST
    };
    std::ranges::stable_sort(list, std::ranges::greater{}, &HostBackend::priority);
    return list;
}

}  // namespace

std::span<const HostBackend* const> host_backends() {
    static const auto list = sorted_backends();
    return list;
}

const HostBackend* find_host(std::string_view name) {
    const auto all = host_backends();
    const auto it = std::ranges::find(all, name, &HostBackend::name);
    return it == all.end() ? nullptr : *it;
}

const HostBackend* best_host() {
    for (const HostBackend* b : host_backends())
        if (!b->available || b->available()) return b;
    return nullptr;
}

}  // namespace lx::display
